drop policy if exists "School users access transport routes" on public.school_transport_routes;
create policy "School users read transport routes" on public.school_transport_routes for select to authenticated using (exists(select 1 from public.school_tenants t where t.school_id=school_transport_routes.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_routes.school_id and r.user_id=(select auth.uid()) and r.status='active' and r.allowed_pages && array['Routes','Buses','Allotment']::text[]));
create policy "School admins and route managers write routes" on public.school_transport_routes for all to authenticated using (exists(select 1 from public.school_tenants t where t.school_id=school_transport_routes.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_routes.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Routes'=any(r.allowed_pages))) with check (exists(select 1 from public.school_tenants t where t.school_id=school_transport_routes.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_routes.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Routes'=any(r.allowed_pages)));
drop policy if exists "School users access transport stops" on public.school_transport_stops;
create policy "School users read transport stops" on public.school_transport_stops for select to authenticated using (exists(select 1 from public.school_tenants t where t.school_id=school_transport_stops.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_stops.school_id and r.user_id=(select auth.uid()) and r.status='active' and r.allowed_pages && array['Routes','Buses','Allotment']::text[]));
create policy "School admins and route managers write stops" on public.school_transport_stops for all to authenticated using (exists(select 1 from public.school_tenants t where t.school_id=school_transport_stops.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_stops.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Routes'=any(r.allowed_pages))) with check (exists(select 1 from public.school_tenants t where t.school_id=school_transport_stops.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_stops.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Routes'=any(r.allowed_pages)));
drop policy if exists "School users access transport buses" on public.school_transport_buses;
create policy "School users read transport buses" on public.school_transport_buses for select to authenticated using (exists(select 1 from public.school_tenants t where t.school_id=school_transport_buses.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_buses.school_id and r.user_id=(select auth.uid()) and r.status='active' and r.allowed_pages && array['Buses','Allotment']::text[]));
create policy "School admins and bus managers write buses" on public.school_transport_buses for all to authenticated using (exists(select 1 from public.school_tenants t where t.school_id=school_transport_buses.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_buses.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Buses'=any(r.allowed_pages))) with check (exists(select 1 from public.school_tenants t where t.school_id=school_transport_buses.school_id and t.admin_user_id=(select auth.uid())) or exists(select 1 from public.school_user_roles r where r.school_id=school_transport_buses.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Buses'=any(r.allowed_pages)));
drop policy if exists "Transport users read student records for allotment" on public.school_people;
create policy "Transport users read student records for allotment" on public.school_people for select to authenticated using(record_type='Student' and exists(select 1 from public.school_user_roles r where r.school_id=school_people.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Allotment'=any(r.allowed_pages)));
drop policy if exists "Bus managers read transport staff" on public.school_people;
create policy "Bus managers read transport staff" on public.school_people for select to authenticated using(record_type='Driver & Cleaner' and exists(select 1 from public.school_user_roles r where r.school_id=school_people.school_id and r.user_id=(select auth.uid()) and r.status='active' and 'Buses'=any(r.allowed_pages)));
create or replace function public.validate_school_transport_allotment() returns trigger language plpgsql set search_path=public as $$ declare bus_capacity integer; bus_route uuid; bus_status text; active_count integer; stop_route uuid; begin
select capacity,route_id,status into bus_capacity,bus_route,bus_status from public.school_transport_buses where school_id=new.school_id and id=new.bus_id;
if not found then raise exception 'Selected bus was not found in this school.'; end if;
if bus_route<>new.route_id then raise exception 'Selected bus does not belong to the selected route.'; end if;
if new.status='active' and bus_status<>'active' then raise exception 'Only active buses can receive new student allotments.'; end if;
if new.pickup_stop_id is not null then select route_id into stop_route from public.school_transport_stops where school_id=new.school_id and id=new.pickup_stop_id; if not found or stop_route<>new.route_id then raise exception 'Pickup stop must belong to the selected route.'; end if; end if;
if new.status='active' then select count(*) into active_count from public.school_transport_allotments where school_id=new.school_id and bus_id=new.bus_id and status='active' and id is distinct from new.id; if active_count>=bus_capacity then raise exception 'Selected bus has reached its seating capacity.'; end if; end if;
return new; end; $$;
drop trigger if exists validate_school_transport_allotment on public.school_transport_allotments;
create trigger validate_school_transport_allotment before insert or update on public.school_transport_allotments for each row execute function public.validate_school_transport_allotment();